#!/usr/bin/env bash
set -euo pipefail

if [[ ${EUID} -eq 0 ]]; then echo 'Run agentos-home as the workstation user.' >&2; exit 1; fi
state_dir="$HOME/.local/share/agentos-home"; mkdir -p "$state_dir"
html="$state_dir/index.html"; port_file="$state_dir/port"; pid_file="$state_dir/server.pid"; log_file="$state_dir/server.log"; ui_file="$state_dir/ui-command"

if ! curl -fsS http://127.0.0.1:4787/v1/healthz >/dev/null 2>&1; then
  systemctl --user start agentosd.service >/dev/null 2>&1 || true
  for _ in {1..40}; do curl -fsS http://127.0.0.1:4787/v1/healthz >/dev/null 2>&1 && break; sleep .1; done
fi
curl -fsS http://127.0.0.1:4787/v1/healthz >/dev/null || { echo 'agentosd is not available.' >&2; exit 1; }

cat > "$html" <<'EOF'
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AgentOS</title>
<style>
:root{color-scheme:dark;--bg:#05070b;--panel:#0b1017;--line:#202a39;--text:#f4f6fa;--muted:#7f8a9c;--purple:#8b5cf6;--green:#3ddc84;--amber:#ffb84d;--red:#ff6474;--blue:#55b8ff}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--text);font:13px Inter,system-ui,sans-serif}body{background:radial-gradient(circle at 68% 16%,#211344 0,#0a0d14 31%,#05070b 65%)}button,input{font:inherit}.app{display:grid;grid-template-columns:220px 1fr;grid-template-rows:52px 1fr;height:100vh}.top{grid-column:1/3;display:flex;align-items:center;gap:20px;padding:0 18px;border-bottom:1px solid var(--line);background:#070a0fef}.brand{font-weight:760}.brand b{color:var(--purple)}.tabs{display:flex;gap:5px}.tab{border:0;background:transparent;color:var(--muted);padding:9px 12px;border-radius:7px;cursor:pointer}.tab.active{background:#151a24;color:white}.spacer{flex:1}.pill{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--green)}.side{border-right:1px solid var(--line);padding:16px 12px;background:#070a10d8;overflow:auto}.label{font:10px ui-monospace,monospace;color:var(--muted);letter-spacing:.14em;margin:9px 8px}.project{width:100%;text-align:left;border:1px solid transparent;background:transparent;color:white;padding:10px;border-radius:8px;cursor:pointer;margin-bottom:3px}.project:hover,.project.active{background:#111722;border-color:#293246}.project small{display:block;color:var(--muted);margin-top:3px}.quick{width:100%;margin-top:4px;padding:10px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--text);text-align:left;cursor:pointer}.quick:hover{background:#111722}.key{float:right;color:#667184;font:10px ui-monospace,monospace}.main{padding:20px 22px;overflow:auto}.view{display:none}.view.active{display:block}.hero{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px}.hero h1{font-size:26px;margin:0 0 5px}.hero p{margin:0;color:var(--muted)}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{background:#101620;border:1px solid var(--line);color:white;border-radius:8px;padding:9px 12px;cursor:pointer}.btn:hover{border-color:#4a586c}.btn.primary{background:var(--purple);border-color:var(--purple)}.btn.danger{border-color:#5b2630;color:#ff9aa6}.grid{display:grid;gap:12px}.metrics{grid-template-columns:repeat(5,1fr);margin-bottom:12px}.metric,.card{background:#0b1018df;border:1px solid var(--line);border-radius:10px}.metric{padding:13px}.metric small{color:var(--muted);text-transform:uppercase;font-size:10px;letter-spacing:.12em}.metric b{display:block;font-size:21px;margin-top:8px}.workspaceTop{grid-template-columns:minmax(0,1.5fr) minmax(300px,.8fr);margin-bottom:12px}.card{padding:14px}.card h3{margin:0 0 11px;font-size:13px}.mono{font-family:ui-monospace,SFMono-Regular,monospace}.muted{color:var(--muted)}.rows{display:flex;flex-direction:column;gap:7px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 10px;border:1px solid #1f2836;border-radius:8px;background:#090d13}.row strong{font-size:12px}.row small{color:var(--muted)}.status{font-size:10px;padding:4px 7px;border-radius:999px;background:#121925;color:var(--muted);white-space:nowrap}.status.ok{color:var(--green)}.status.warn{color:var(--amber)}.status.bad{color:var(--red)}.status.info{color:var(--blue)}.split{display:grid;grid-template-columns:1fr 1fr;gap:12px}.activeWork{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:10px}.sessionCard{border:1px solid #222d3c;background:linear-gradient(145deg,#0b111a,#090c12);border-radius:10px;padding:13px;min-height:166px}.sessionHead{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px}.sessionHead strong{font-size:14px;text-transform:capitalize}.agentDot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green);margin-right:7px}.agentDot.wait{background:var(--amber)}.agentDot.bad{background:var(--red)}.agentDot.bg{background:var(--blue)}.sessionMeta{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:10px}.sessionMeta div{border:1px solid #1c2532;border-radius:7px;padding:7px}.sessionMeta small{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.sessionMeta b{display:block;margin-top:4px;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.taskLine{border-left:2px solid var(--purple);padding:7px 9px;margin:8px 0;background:#0c1018}.githubBox{margin-top:9px;border-top:1px solid #1b2330;padding-top:9px}.githubTitle{display:flex;align-items:center;justify-content:space-between;margin-bottom:7px}.githubLine{display:grid;grid-template-columns:64px 1fr auto;gap:8px;align-items:center;padding:7px 0}.githubLine+.githubLine{border-top:1px solid #151d28}.githubLine a{color:var(--text);text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.githubLine a:hover{color:var(--blue)}.commit{padding:8px 0;border-bottom:1px solid #171f2b}.commit:last-child{border:0}.activity{display:grid;grid-template-columns:88px 1fr auto;gap:10px;padding:9px 0;border-bottom:1px solid #171f2b}.activity b{font-size:10px;text-transform:uppercase;color:var(--purple)}.resource{display:grid;grid-template-columns:1fr 70px 80px;gap:10px;padding:7px 0;border-bottom:1px solid #171f2b}.palette{position:fixed;inset:0;background:#000a;display:none;align-items:flex-start;justify-content:center;padding-top:10vh;z-index:20}.palette.open{display:flex}.paletteBox{width:min(760px,80vw);background:#0c1119;border:1px solid #303a4b;border-radius:14px;box-shadow:0 30px 100px #000;padding:12px}.palette input{width:100%;background:#131a25;border:1px solid var(--line);border-radius:9px;padding:13px;color:white;outline:none}.cmds{margin-top:9px;max-height:55vh;overflow:auto}.cmd{width:100%;display:flex;justify-content:space-between;background:transparent;border:0;border-radius:7px;color:white;padding:10px;text-align:left;cursor:pointer}.cmd:hover{background:#151c28}.empty{color:var(--muted);padding:24px;text-align:center}.sectionTitle{display:flex;align-items:center;justify-content:space-between;margin:4px 0 9px}.sectionTitle h3{margin:0}.sectionTitle small{color:var(--muted)}:focus-visible{outline:3px solid var(--blue);outline-offset:2px}[hidden]{display:none!important}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}.workspaceTop,.split{grid-template-columns:1fr}.app{grid-template-columns:180px 1fr}}
</style><style>.attentionRow{align-items:flex-start;flex-wrap:wrap}.attentionText{flex:1;min-width:180px}.attentionActions{margin-left:auto}</style></head><body><div class="app">
<div class="top"><div class="brand"><b>▲</b> AgentOS</div><div class="tabs"><button class="tab active" data-view="workspace">Workspace</button><button class="tab" data-view="agents">Agents</button><button class="tab" data-view="activity">Activity</button><button class="tab" data-view="system">System</button></div><div class="spacer"></div><div class="pill"><span class="dot" id="netdot"></span><span id="host">agentos</span></div><div class="pill" id="clock"></div></div>
<aside class="side"><div class="label">PROJECTS</div><div id="projects"></div><div class="label">QUICK</div><button class="quick" onclick="action('terminal')">Terminal <span class="key">⌘↵</span></button><button class="quick" onclick="openPalette()">Command palette <span class="key">⌘K / F8</span></button><button class="quick" onclick="action('files')">Files</button><button class="quick" onclick="action('browser')">Browser</button></aside>
<main class="main">
<section class="view active" id="workspace"><div class="hero"><div><h1>Agent workstation</h1><p>Live projects, authoritative agent events, PRs and CI from <span class="mono">agentosd</span>.</p></div><div class="actions"><button class="btn" onclick="action('files')">Files</button><button class="btn" onclick="action('browser')">Browser</button><button class="btn primary" onclick="action('terminal')">New terminal</button></div></div><div class="grid metrics" id="metrics"></div><div class="grid workspaceTop"><div class="card"><h3 id="projectTitle">Active project</h3><div id="projectBody"></div></div><div class="card"><h3>Attention inbox</h3><div id="attention"></div></div></div><div class="card"><div class="sectionTitle"><h3>Active work</h3><small id="workSummary"></small></div><div id="activeWork" class="activeWork"></div></div></section>
<section class="view" id="agents"><div class="hero"><div><h1>Agents</h1><p>Persistent AI sessions. Hook/adapter events override process inference when available.</p></div></div><div class="split"><div class="card"><h3>Sessions</h3><div id="agentSessions" class="rows"></div></div><div class="card"><h3>Start agent</h3><div class="rows" id="agentLaunch"></div></div><div class="card"><h3>Developer tools</h3><p class="muted">Optional tools are installed only when selected.</p><div id="developerTools" class="rows"></div></div><div class="card"><h3>Loaded models</h3><div id="models"></div></div><div class="card"><h3>Resource attribution</h3><div id="resources"></div></div></div></section>
<section class="view" id="activity"><div class="hero"><div><h1>Activity</h1><p>Persistent agent/tool events, GitHub state and recent commits.</p></div></div><div class="split"><div class="card"><h3>Runtime events</h3><div id="events"></div></div><div class="card"><h3>GitHub</h3><div id="githubActivity"></div></div><div class="card"><h3>Recent commits</h3><div id="commits"></div></div></div></section>
<section class="view" id="system"><div class="hero"><div><h1>System</h1><p>Updates, hardware readiness, recovery, support and native KDE settings.</p></div></div><div class="card"><h3>Start here</h3><p>1. Review Health and Hardware readiness. 2. Check Update Center. 3. Use Recovery Center before risky changes.</p><p class="muted">Actions that change the machine open a visible confirmation flow. Firmware, reboot, and rollback stay separate.</p></div><p class="muted" id="systemNotice" role="status">System information is loading…</p><div class="split"><div class="card"><h3>Environment</h3><div id="environment"></div></div><div class="card"><h3>Health</h3><div id="health"></div></div><div class="card"><h3>Update Center</h3><div id="updates"></div></div><div class="card"><h3>Hardware readiness</h3><div id="hardware"></div></div><div class="card"><h3>System settings</h3><p class="muted" id="settingsSummary">Native KDE settings retain Linux/Polkit authorization.</p><div class="actions" id="systemSettings"></div></div><div class="card"><h3>Recovery Center</h3><div id="recovery"></div><div class="actions"><button class="btn" onclick="action('snapshot')">Create snapshot</button></div></div><div class="card"><h3>Connectivity</h3><div id="services"></div></div><div class="card"><h3>Support &amp; privacy</h3><p class="muted">Reports stay local and redact secrets. Review the file before sharing it. Telemetry is disabled by default.</p><div class="actions"><button class="btn" onclick="action('doctor')">Run Doctor</button><button class="btn" onclick="action('support')">Create local report</button></div></div></div></section>
</main></div>
<div class="palette" id="palette" onclick="if(event.target===this)closePalette()"><div class="paletteBox"><input id="cmdq" placeholder="Search projects, agents or commands…"><div class="cmds" id="cmds"></div></div></div>
<script>
let S=null,activeProject=''; const agents=['claude','codex','hermes','herdr'];
const $=id=>document.getElementById(id); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opts){const r=await fetch(path,opts);if(!r.ok){const body=await r.json().catch(()=>null);throw new Error(body?.error?.message||`Request failed (${r.status})`)}return r.status===204?null:r.json()}
async function action(name,extra={}){try{await api('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,...extra})});closePalette();setTimeout(refresh,400)}catch(e){alert(e.message)}}
function setView(v){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===v));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===v))}
document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>setView(x.dataset.view));
function metric(k,v){return `<div class="metric"><small>${esc(k)}</small><b>${esc(v)}</b></div>`}
function statusClass(s){s=(s||'').toLowerCase();if(['blocked','failure','failed','check-failed','apply-failed','cancelled','timed_out','action_required'].includes(s))return'bad';if(['warning','waiting','queued','in_progress','pending','checking','available','reboot-required','neutral','stale','starting','thinking','tool'].includes(s))return'warn';if(['ready','running','success','succeeded','up-to-date','completed','approved','clean','mergeable','done'].includes(s))return'ok';return'info'}
function sessionCard(s){const project=s.project||'workspace',cls=statusClass(s.status),dot=s.status==='WAITING'?'wait':['BLOCKED','FAILED'].includes(s.status)?'bad':s.status==='BACKGROUND'?'bg':'';const task=s.task?.title?`<div class="taskLine"><small class="muted">TASK</small><div>${esc(s.task.title)}</div></div>`:'';return `<div class="sessionCard"><div class="sessionHead"><strong><span class="agentDot ${dot}"></span>${esc(s.agent)}</strong><span class="status ${cls}">${esc(s.status||'RUNNING')} · ${esc(s.elapsed)}</span></div>${task}<div class="sessionMeta"><div><small>Project</small><b>${esc(project)}</b></div><div><small>PID</small><b class="mono">${s.pid}</b></div><div><small>State source</small><b>${esc(s.status_source||'process')}</b></div><div><small>Session</small><b class="mono">${esc(s.id||'n/a')}</b></div></div><div class="actions">${project!=='workspace'?`<button class="btn" onclick="action('project-open',{project:'${esc(project)}'})">Attach</button><button class="btn" onclick="action('project-diff',{project:'${esc(project)}'})">Diff</button>`:''}<button class="btn" onclick="setView('activity')">Events</button><button class="btn danger" onclick="action('agent-stop',{agent:'${esc(s.agent)}',project:'${esc(project)}',pid:${s.pid}})">Stop</button></div></div>`}
function githubHTML(p){if(!p||!p.github||!p.github.available)return '<div class="muted">GitHub state unavailable</div>';const g=p.github,pr=g.pr,ci=g.ci;let h=`<div class="githubBox"><div class="githubTitle"><strong>${esc(g.repo)}</strong><span class="muted">30s cache</span></div>`;h+=pr?`<div class="githubLine"><span class="muted">PR #${pr.number}</span><a href="${esc(pr.url)}" target="_blank">${esc(pr.title)}</a><span class="status ${statusClass(pr.review_decision||pr.merge_state)}">${esc(pr.draft?'DRAFT':pr.review_decision||pr.merge_state||'OPEN')}</span></div>`:`<div class="githubLine"><span class="muted">PR</span><span>No open PR for branch</span><span></span></div>`;h+=ci?`<div class="githubLine"><span class="muted">CI</span><a href="${esc(ci.url)}" target="_blank">${esc(ci.name||'workflow')}</a><span class="status ${statusClass(ci.conclusion||ci.status)}">${esc((ci.conclusion||ci.status||'unknown').toUpperCase())}</span></div>`:`<div class="githubLine"><span class="muted">CI</span><span>No workflow run found</span><span></span></div>`;return h+'</div>'}
function maintenanceActionAvailable(id){return(S.maintenance?.actions||[]).some(a=>a.id===id&&a.available)}
function hardwareLabel(id){return({'architecture':'Architecture','machine-role':'Machine role','boot-mode':'Boot mode','root-filesystem':'Root filesystem','recovery':'Recovery','connectivity':'Connectivity','graphical-session':'Graphical session','firmware-support':'Firmware support'})[id]||id||'Hardware check'}
function hardwareHTML(){const h=S.hardware||{},checks=h.checks||[],f=h.firmware||{};let out=`<div class="row"><span>Overall</span><span class="status ${statusClass(h.overall)}">${esc(h.overall||'unavailable')}</span></div><div class="row"><span>Machine role</span><strong>${esc(h.role||'unknown')}</strong></div>`;out+=checks.map(c=>`<div class="row"><span><strong>${esc(hardwareLabel(c.id))}</strong><small> · ${esc(c.detail||'No detail available')}</small></span><span class="status ${statusClass(c.status)}">${esc(c.status||'unavailable')}</span></div>`).join('')||'<div class="empty">Hardware readiness is unavailable.</div>';out+=`<div class="row"><span><strong>Firmware</strong><small> · ${esc(f.detail||'fwupd is optional')}</small></span><span class="status ${statusClass(f.status)}">${esc(f.status||'unavailable')}</span></div>`;out+='<div class="actions">';if(maintenanceActionAvailable('firmware-enable'))out+='<button class="btn" onclick="action(\'firmware-enable\')">Enable firmware support</button>';if(maintenanceActionAvailable('firmware-check'))out+='<button class="btn" onclick="action(\'firmware-check\')">Check firmware</button>';if(maintenanceActionAvailable('firmware-apply'))out+=`<button class="btn" ${f.updates>0?'':'disabled'} onclick="action('firmware-apply')">Apply firmware updates</button>`;return out+'</div>'}
function recoveryHTML(){const r=S.recovery||{},points=r.points||[],recommended=points.find(p=>p.boot_safe),staged=r.staged;let h=`<div class="row"><span>Status</span><span class="status ${statusClass(r.status)}">${esc(r.status||'unavailable')}</span></div><div class="row"><span>Current root</span><strong>${esc(r.current_root||'unknown')}${r.current_rollback?' · rollback active':''}</strong></div><div class="row"><span>Next boot</span><strong class="status ${r.next_boot==='rollback-once'?'warn':'info'}">${esc(r.next_boot||'unknown')}</strong></div>`;if(staged)h+=`<div class="row"><span>Staged from</span><strong>${esc(staged.source_id||'unknown')}</strong></div>`;h+=`<p class="muted">${r.next_boot==='rollback-once'?'Only the next boot uses this recovery point. Reboot remains a separate decision; a later boot returns to normal.':'Boot-safe points include a verified matching kernel and initramfs bundle. Root-only points cannot be staged here.'}</p>`;h+=points.map(p=>{const id=String(p.id||''),canStage=p.boot_safe&&maintenanceActionAvailable('recovery-stage');return `<div class="row"><span><strong class="mono">${esc(id)}</strong>${recommended&&recommended.id===p.id?' <small>· recommended</small>':''}</span><span class="actions"><span class="status ${p.boot_safe?'ok':'info'}">${p.boot_safe?'boot-safe':'root-only'}</span><button class="btn" ${canStage?'':'disabled'} onclick='action("recovery-stage",{recovery_point_id:${JSON.stringify(id)}})'>Stage for next boot</button></span></div>`}).join('')||'<div class="empty">No recovery points are available yet.</div>';if(staged)h+=`<div class="actions"><button class="btn danger" ${maintenanceActionAvailable('recovery-cancel')?'':'disabled'} onclick="action('recovery-cancel')">Cancel staged rollback</button></div>`;return h}
function render(){if(!S)return;$('systemNotice').hidden=true;$('host').textContent=S.host;$('netdot').style.background=S.health.tailscale?'var(--green)':'var(--red)';if(!activeProject&&S.projects.length)activeProject=S.projects[0].name;
$('projects').innerHTML=S.projects.map(p=>`<button class="project ${p.name===activeProject?'active':''}" onclick="activeProject='${esc(p.name)}';render()"><b>${esc(p.name)}</b><small>${esc(p.branch)}${p.dirty?' · '+p.dirty_count+' modified':''}${p.github?.ci?' · CI '+(p.github.ci.conclusion||p.github.ci.status):''}</small></button>`).join('')||'<div class="empty">No projects</div>';
$('metrics').innerHTML=metric('Uptime',S.uptime)+metric('Load',S.load)+metric('Memory',S.health.memory_pct+'%')+metric('Disk',S.health.disk_pct+'%')+metric('Health',S.health.status.toUpperCase());
const p=S.projects.find(x=>x.name===activeProject);$('projectTitle').textContent=p?`Active project · ${p.name}`:'Active project';$('projectBody').innerHTML=p?`<div class="rows"><div class="row"><span>Branch</span><strong class="mono">${esc(p.branch)}</strong></div><div class="row"><span>Working tree</span><strong>${p.dirty?p.dirty_count+' changed files':'clean'}</strong></div><div class="row"><span>Upstream</span><strong>${p.upstream?esc(p.upstream)+' · ↑'+p.ahead+' ↓'+p.behind:'none'}</strong></div><div class="row"><span>Worktrees</span><strong>${p.worktrees}</strong></div><div class="row"><span>Last activity</span><strong>${esc(p.last_activity||'n/a')}</strong></div><div class="actions"><button class="btn primary" onclick="action('project-open',{project:'${esc(p.name)}'})">Open Herdr</button><button class="btn" onclick="action('project-diff',{project:'${esc(p.name)}'})">Diff</button></div></div>${githubHTML(p)}`:'<div class="empty">Choose a project</div>';
const attention=(S.attention||[]).filter(a=>!a.project||!activeProject||a.project===activeProject||a.kind==='system');$('attention').innerHTML=attention.map(a=>{const id=JSON.stringify(a.id||'');const label=esc(a.text||'attention item');return `<div class="row attentionRow"><span class="attentionText">${a.agent?`<strong>${esc(a.agent)}</strong> · `:''}${label}</span><span class="status ${statusClass(a.level==='critical'?'failed':a.level==='warning'?'waiting':a.kind==='agent'?'waiting':'running')}">${esc(a.kind.toUpperCase())}</span>${a.id?`<span class="actions attentionActions"><button class="btn" aria-label="Acknowledge ${label}" onclick='action("attention-acknowledge",{attention_id:${id}})'>Acknowledge</button><button class="btn danger" aria-label="Dismiss ${label}" onclick='action("attention-dismiss",{attention_id:${id}})'>Dismiss</button></span>`:''}</div>`}).join('')||'<div class="row"><span>Workspace state</span><span class="status ok">NO ATTENTION NEEDED</span></div>';
$('workSummary').textContent=S.sessions.length?`${S.sessions.length} live session${S.sessions.length===1?'':'s'} · ${(S.attention||[]).filter(a=>a.kind==='agent').length} need attention`:'No agents running';$('activeWork').innerHTML=S.sessions.length?S.sessions.map(sessionCard).join(''):`<div class="empty" style="grid-column:1/-1">No active agents. Start one from Agents or use the command palette.</div>`;
$('agentSessions').innerHTML=S.sessions.map(s=>`<div class="row"><span><strong>${esc(s.agent)}</strong><small> · ${esc(s.project)} · ${esc(s.status_source)}</small></span><span class="status ${statusClass(s.status)}">${esc(s.status)} · ${esc(s.elapsed)}</span></div>`).join('')||'<div class="empty">No agents running</div>';
$('agentLaunch').innerHTML=agents.map(a=>`<div class="row"><span><strong>${a[0].toUpperCase()+a.slice(1)}</strong><small> · ${esc(activeProject||'workspace')}</small></span><button class="btn" onclick="action('agent-start',{agent:'${a}',project:'${esc(activeProject)}'})">Start</button></div>`).join('');
$('models').innerHTML=S.models.length?S.models.map(m=>`<div class="row"><span>${esc(m.name)}</span><span class="status ok">${esc(m.processor)}</span></div>`).join(''):'<div class="empty">No local model loaded</div>';$('resources').innerHTML=S.resources.map(r=>`<div class="resource"><span>${esc(r.name)}</span><span class="mono">${r.pid}</span><strong>${r.mb} MB</strong></div>`).join('');
