$('updates').innerHTML=`<div class="row"><span>Status</span><span class="status ${statusClass(updateStatus)}">${esc(updateStatus)}</span></div><div class="row"><span>Channel</span><strong>${esc(u.channel||'unknown')}</strong></div><div class="row"><span>Installed</span><strong>${esc(u.current_version||u.version||'unknown')}</strong></div>${u.target_version?`<div class="row"><span>Available</span><strong>${esc(u.target_version)}</strong></div>`:''}<div class="row"><span>Arch packages pending</span><strong>${u.arch_pending||0}</strong></div><div class="row"><span>Last check</span><strong>${esc(u.checked_at||'never')}</strong></div><div class="row"><span>Last successful update</span><strong>${esc(u.last_success_at||'never')}</strong></div>${u.last_failure?`<div class="row"><span>Problem</span><strong class="status bad">${esc(u.last_failure)}</strong></div>`:''}${u.snapshot_id?`<div class="row"><span>Recovery point</span><strong>${esc(u.snapshot_id)} · migration ${esc(u.migration_status||'unknown')}</strong></div>`:''}${u.reboot_required?'<div class="row"><span>Restart</span><strong class="status warn">Required when convenient; never automatic</strong></div>':''}<div class="actions"><button class="btn" ${updateStatus==='checking'?'disabled':''} onclick="action('update-check')">${updateStatus==='checking'?'Checking…':'Check'}</button><button class="btn primary" ${canUpdate?'':'disabled'} onclick="action('update-apply')">Update now</button></div>`;
