$('developerTools').innerHTML=(S.developer_tools||[]).map(t=>`<div class="row"><span><strong>${esc(t.name)}</strong><small> · ${esc(t.command)}</small></span>${t.installed?`<span class="actions"><span class="status ok">installed</span><button class="btn" onclick="action('open-${esc(t.id)}')">Open</button></span>`:`<span class="actions"><span class="status">optional</span><button class="btn" onclick="action('install-${esc(t.id)}')">Install</button></span>`}</div>`).join('')||'<div class="empty">No optional tools registered</div>';$('services').innerHTML=[['SSH',S.health.ssh],['Tailscale',!!S.health.tailscale],['KRDP',S.health.krdp],['NetworkManager',S.health.network_manager],['Wi-Fi',S.health.wifi&&S.health.wifi!=='disabled'&&S.health.wifi!=='unavailable'],['Bluetooth',S.health.bluetooth],['Ollama',S.health.ollama]].map(([n,v])=>`<div class="row"><span>${n}</span><span class="status ${v?'ok':'bad'}">${typeof v==='string'?esc(v):(v?'online':'offline')}</span></div>`).join('');buildCommands()}
function buildCommands(){const base=[['New terminal',()=>action('terminal')],['Files',()=>action('files')],['Browser',()=>action('browser')],['Workspace view',()=>setView('workspace')],['Agents view',()=>setView('agents')],['Activity view',()=>setView('activity')],['System view',()=>setView('system')],['Doctor',()=>action('doctor')],['Create local support report',()=>action('support')],['Sync workstation',()=>action('sync')],['Check updates',()=>action('update-check')],['Update now',()=>action('update-apply')],['Restart KRDP',()=>action('restart-krdp')],['System settings',()=>action('system-settings')],['Wi-Fi settings',()=>action('wifi-settings')],['Bluetooth settings',()=>action('bluetooth-settings')],['Mouse settings',()=>action('mouse-settings')]];S.projects.forEach(p=>{base.push(['Open project · '+p.name,()=>action('project-open',{project:p.name})]);base.push(['Diff project · '+p.name,()=>action('project-diff',{project:p.name})])});agents.forEach(a=>base.push(['Start '+a+' · '+(activeProject||'workspace'),()=>action('agent-start',{agent:a,project:activeProject})]));(S.developer_tools||[]).forEach(t=>base.push([(t.installed?'Open ':'Install ')+t.name,()=>action((t.installed?'open-':'install-')+t.id)]));const recommended=(S.recovery?.points||[]).find(p=>p.boot_safe);if(recommended&&maintenanceActionAvailable('recovery-stage'))base.push(['Stage recommended recovery point',()=>action('recovery-stage',{recovery_point_id:recommended.id})]);if(maintenanceActionAvailable('recovery-cancel'))base.push(['Cancel staged rollback',()=>action('recovery-cancel')]);window.commands=base;filterCommands('')}
function openPalette(){$('palette').classList.add('open');$('cmdq').value='';filterCommands('');setTimeout(()=>$('cmdq').focus(),0)}function closePalette(){$('palette').classList.remove('open')}function filterCommands(q){q=q.toLowerCase();const hits=(window.commands||[]).filter(([n])=>n.toLowerCase().includes(q));$('cmds').innerHTML=hits.map(([n],i)=>`<button class="cmd" onclick="window.__hits[${i}][1]()"><span>${esc(n)}</span><span class="muted">↵</span></button>`).join('');window.__hits=hits}
$('cmdq').oninput=()=>filterCommands($('cmdq').value);document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(((e.metaKey||e.ctrlKey)&&k==='k')||e.key==='F8'){e.preventDefault();openPalette()}if(e.key==='Escape')closePalette();if(e.altKey&&['1','2','3','4'].includes(e.key)){e.preventDefault();setView(['workspace','agents','activity','system'][Number(e.key)-1])}});
async function pollUI(){try{const r=await fetch('/api/ui-command',{cache:'no-store'});if(r.status===204)return;const j=await r.json();if(j.command==='palette')openPalette();else if(['workspace','agents','activity','system'].includes(j.command))setView(j.command)}catch(e){}}
async function refresh(){try{S=await api('/api/state');render()}catch(e){const notice=$('systemNotice');notice.hidden=false;notice.textContent='System information unavailable. Use Refresh or run AgentOS Doctor.';console.error(e)}}setInterval(refresh,5000);setInterval(pollUI,500);refresh();pollUI();setInterval(()=>$('clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),1000);
</script></body></html>
