import http.server, json, os, pathlib, sys, urllib.request
html, port_file, pid_file, ui_file=sys.argv[1:]
class H(http.server.BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def proxy(self,path,method='GET',body=None):
        req=urllib.request.Request('http://127.0.0.1:4787'+path,data=body,method=method,headers={'Content-Type':'application/json'})
        try:
            with urllib.request.urlopen(req,timeout=15) as r:
                data=r.read(); self.send_response(r.status); self.send_header('Content-Type',r.headers.get('Content-Type','application/json')); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data)
        except Exception as e:
            data=str(e).encode(); self.send_response(502); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data)
    def do_GET(self):
        if self.path in ('/','/index.html'):
            data=pathlib.Path(html).read_bytes(); self.send_response(200); self.send_header('Content-Type','text/html'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data)
        elif self.path=='/api/state': self.proxy('/v1/state')
        elif self.path=='/api/ui-command':
            p=pathlib.Path(ui_file)
            if not p.exists(): self.send_response(204); self.end_headers(); return
            try: command=p.read_text().strip(); p.unlink(missing_ok=True)
            except Exception: command=''
            if not command: self.send_response(204); self.end_headers(); return
            data=json.dumps({'command':command}).encode(); self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data)
        else: self.send_error(404)
    def do_POST(self):
        if self.path!='/api/action': self.send_error(404); return
        n=int(self.headers.get('Content-Length','0')); self.proxy('/v1/action','POST',self.rfile.read(n))
class S(http.server.ThreadingHTTPServer): allow_reuse_address=True
with S(('127.0.0.1',0),H) as s:
    pathlib.Path(port_file).write_text(str(s.server_address[1])); pathlib.Path(pid_file).write_text(str(os.getpid())); s.serve_forever()
PY
